        "F = t^(2-alpha) * phi_F(h * t^(-beta-gamma))",
        "C = t^(-alpha) * phi_C(h * t^(-beta-gamma))",
        "chi = t^(-gamma) * phi_chi(h * t^(-beta-gamma))",
        "Gamma_H = t^(1-beta-gamma) * phi_Gamma(h * t^(-beta-gamma))"
      ],
      "variable_names": [
        "t",
        "h",
        "beta",
        "gamma",
        "alpha",
        "phi_F",
